FormulaFieldDefinitions.FormulaFieldDefinition:
if {AC_MAST.AC_GSTNO} = "" then
    '                              State :  ' & {AC_MAST.AC_STATE}&  '      Pan No.:  ' & {AC_MAST.AC_PANNO}
else
   {AC_MAST.AC_GSTNO} &  '         State :  ' & {AC_MAST.AC_STATE}&  '      Pan No.:  ' & {AC_MAST.AC_PANNO}

if{SL_DATA.ADD1} <> '' then
    {SL_DATA.MOBILE}
else
    if {AC_MAST.AC_MOBILE} <> '' then
        {AC_MAST.AC_MOBILE}
    else if {AC_MAST.AC_PHONE} <> '' then
        {AC_MAST.AC_MOBILE}
    else
        {AC_MAST.AC_MOBILE2}

if {CO_MAST.REP_ADD_TYPE} = 'L' THEN
    {LOCT_MAST.LC_CITY} + '   Mo : ' + {LOCT_MAST.LC_MOBILE} + '  Ph : ' + {LOCT_MAST.LC_PHONE}
else
    {CO_MAST.CO_CITY} + '   Mo : ' + {CO_MAST.CO_MOBILE}  + '  Ph : ' + {CO_MAST.CO_PHONE}

numbervar RmVal:=0; 
numbervar Amt:=0; 
numbervar pAmt:=0; 
stringvar InWords :="Rupees :"; 
Amt := ({SL_DATA.TOT_AMT});

if Amt > 10000000 then RmVal := truncate(Amt/10000000); 
if Amt = 10000000 then RmVal := 1; 
if RmVal = 1 then 
InWords := InWords + " " + towords(RmVal,0) + " crore" 
else 
if RmVal > 1 then InWords := InWords + " " + towords(RmVal,0) + " crores";

Amt := Amt - Rmval * 10000000; 
if Amt > 100000 then RmVal := truncate(Amt/100000); 
if Amt = 100000 then RmVal := 1; 
if RmVal >=1 then 
InWords := InWords + " " + towords(RmVal,0) + " lakhs";

Amt := Amt - Rmval * 100000; 
if Amt > 0 then InWords := InWords + " " + towords(truncate(Amt),0); 
pAmt := (Amt - truncate(Amt)) * 100; 
if pAmt > 0 then 
InWords := InWords + " and " + towords(pAmt,0) + " paisa only" 
else 
InWords := InWords + " only"; 
UPPERCASE(InWords)
